<?php
namespace App\Http\Controllers;
use App\Repositories\{LojaRepository,LancamentoRepository,PagamentoRepository};use App\Services\{ClienteService,FiadoService,PagamentoService,WhatsappService};use Illuminate\Http\Request;
class MovimentacaoController extends Controller { public function __construct(private ClienteService $clientes,private FiadoService $fiados,private PagamentoService $pagamentos,private LojaRepository $lojas,private WhatsappService $whatsapp){} private function list(){return collect(app(\App\Repositories\ClienteRepository::class)->where('loja_id',session('loja_id')))->sortBy('nome');} public function createLaunch(Request $r){return view('movements.launch-form',['clientes'=>$this->list(),'selected'=>$r->get('cliente_id')]);} public function storeLaunch(Request $r){$d=$r->validate(['cliente_id'=>'required','valor'=>'required|numeric|min:0.01','descricao'=>'required|max:255','data_vencimento'=>'required|date','tipo'=>'nullable']);try{[$m,$before,$after]=$this->fiados->create(array_merge($d,['data_lancamento'=>now()->toDateString()]));}catch(\DomainException $e){return back()->withInput()->with('error',$e->getMessage());}return redirect()->route('receipt',['tipo'=>'compra','id'=>$m['id']])->with('receipt',compact('m','before','after'));} public function createPay(Request $r){return view('movements.payment-form',['clientes'=>$this->list(),'selected'=>$r->get('cliente_id')]);} public function storePay(Request $r){$d=$r->validate(['cliente_id'=>'required','valor'=>'required|numeric|min:0.01','forma_pagamento'=>'required|in:dinheiro,pix,cartão,outro','observacao'=>'nullable|max:500']);[$m,$before,$after]=$this->pagamentos->create(array_merge($d,['data_pagamento'=>now()->toDateString()]));return redirect()->route('receipt',['tipo'=>'pagamento','id'=>$m['id']])->with('receipt',compact('m','before','after'));} public function receipt(string $tipo,string $id){$repo=$tipo==='compra'?app(LancamentoRepository::class):app(PagamentoRepository::class);$m=$repo->find($id);abort_unless($m&&$m['loja_id']===session('loja_id'),404);$c=$this->clientes->owned($m['cliente_id']);$after=$this->clientes->balance($c['id']);$before=$tipo==='compra'?$after-$m['valor']:$after+$m['valor'];return view('movements.receipt',compact('tipo','m','c','after','before'));} }
